const t = $input.first().json;
const paraNumero = (txt) => Number(String(txt).replace(/[^\d,]/g, '').replace(',', '.'));

return t.nome.map((nome, i) => ({
  json: {
    nome,
    email: t.email[i],
    saldo: t.saldo[i],
    saldoNumero: paraNumero(t.saldo[i]),
    perfil: t.perfil[i],
  },
}));

const produtos = $input.all().map(i => ({
  perfil: String(i.json.perfil).trim(),
  produto: i.json.produto,
  minimo: Number(i.json.minimo),
  rentabilidade: i.json.rentabilidade,
}));
const clientes = $('RPA: Montar lista de clientes').all().map(i => i.json);

const brl = (v) => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const abertura = {
  Conservador: 'pensando na segurança do seu patrimônio, separamos opções de renda fixa com baixo risco e boa liquidez',
  Moderado: 'para equilibrar segurança e crescimento, separamos um mix entre renda fixa e opções com mais potencial de retorno',
  Arrojado: 'para buscar maior potencial de retorno no longo prazo, separamos opções de renda variável',
};

return clientes.map(c => {
  const doPerfil = produtos.filter(p => p.perfil === c.perfil);
  const elegiveis = doPerfil.filter(p => p.minimo <= c.saldoNumero);
  const lista = elegiveis
    .map(p => `- ${p.produto} (aporte mínimo ${brl(p.minimo)}, rentabilidade ${p.rentabilidade})`)
    .join('\n');
  const primeiroNome = c.nome.split(' ')[0];

  const mensagemEstatica = elegiveis.length
    ? `Olá, ${primeiroNome}! Como seu perfil é ${c.perfil}, ${abertura[c.perfil] ?? 'separamos algumas opções'}:\n${lista}\nQuer conversar sobre qual faz mais sentido para você?`
    : `Olá, ${primeiroNome}! Ainda não temos opções do perfil ${c.perfil} com aporte mínimo dentro do seu saldo atual. Que tal conversarmos sobre um plano para chegar lá?`;

  return {
    json: {
      ...c,
      produtosDoPerfil: doPerfil,
      produtosElegiveis: elegiveis,
      listaProdutos: lista || 'nenhum produto elegível para o saldo atual',
      mensagemEstatica,
    },
  };
});

