const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = (s) => esc(s).replace(/\n/g, '<br>');
const itens = $input.all().map(i => i.json);
const cor = { Conservador: '#1E88E5', Moderado: '#FB8C00', Arrojado: '#D81B60' };

const linhas = itens.map(c => `
  <tr>
    <td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><strong>${esc(c.nome)}</strong><br><span style="color:#777;font-size:12px">${esc(c.email)}</span></td>
    <td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><span style="color:${cor[c.perfil] || '#555'};font-weight:bold">${esc(c.perfil)}</span><br>${esc(c.saldo)}</td>
    <td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top">${esc((c.produtosRecomendados || []).join(', ') || '—')}</td>
    <td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top;font-size:13px">${br(c.mensagemIA)}</td>
  </tr>`).join('');

const html = `
<div style="font-family:Arial,sans-serif;color:#222;max-width:900px">
  <h2 style="margin-bottom:4px">Assistente de Investimentos — recomendações do dia</h2>
  <p style="color:#666;margin-top:0">${itens.length} clientes processados em ${$now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm')}. Dados fictícios do lab DIO.</p>
  <table style="border-collapse:collapse;width:100%">
    <thead><tr style="background:#f5f5f5;text-align:left">
      <th style="padding:10px">Cliente</th><th style="padding:10px">Perfil / Saldo</th><th style="padding:10px">Produtos elegíveis</th><th style="padding:10px">Mensagem (IA)</th>
    </tr></thead>
    <tbody>${linhas}</tbody>
  </table>
</div>`;

return [{ json: { assunto: `Recomendações de investimento — ${itens.length} clientes`, html, total: itens.length } }];
